with base as (select * from stores where region in ('South', 'Central', 'East') and opened_date > '2025-06-01' and store_name is not null), Agg as (select case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, round(stddev(sqft), 2) as stddev_sqft from base group by case when year(opened_date) < 2024 then 'before_2024' when year(opened_date) = 2024 then '2024' else 'after_2024' end) select * from Agg where stddev_sqft > 37 order by stddev_sqft, opened_cohort limit 3;
